import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';

export default function Character({ aqi }) {
  // Determine state parameters based on AQI
  let shirtColor = '#10b981'; // emerald-500
  let skinColor = '#fde68a'; // light yellow-ish flat skin
  let eyeProps = { d: "M 80 120 Q 86 115 92 120 M 108 120 Q 114 115 120 120", stroke: "#451a03", width: 4 }; // Happy closed eyes
  let mouthProps = { d: "M 90 140 Q 100 155 110 140", stroke: "#451a03", fill: "rgba(180, 83, 9, 0.2)", width: 4 }; // Big smile
  let eyebrowProps = { d: "M 75 105 Q 85 100 95 105 M 105 105 Q 115 100 125 105" }; // Raised happy brows
  let hasMask = false;
  let shoulderPath = "M 40 280 C 40 190 160 190 160 280 Z"; // Upright
  let headOffsetY = 0;
  let bgGradient = "radial-gradient(circle, rgba(16, 185, 129, 0.15) 0%, transparent 60%)";
  let sweatVisible = 0;
  let fogVisible = 0;

  if (aqi > 50 && aqi <= 100) {
    // MODERATE: Yellow, neutral/tired, slight slouch
    shirtColor = '#eab308'; // yellow-500
    shoulderPath = "M 35 285 C 45 205 155 205 165 285 Z"; // Slouched
    eyeProps = { d: "M 78 120 L 92 120 M 108 120 L 122 120", stroke: "#451a03", width: 4 }; // Neutral flat eyes
    mouthProps = { d: "M 90 145 Q 100 142 110 145", stroke: "#451a03", fill: "none", width: 4 }; // Slight frown
    eyebrowProps = { d: "M 75 105 L 90 105 M 110 105 L 125 105" }; // Flat brows
    headOffsetY = 8;
    bgGradient = "radial-gradient(circle, rgba(234, 179, 8, 0.15) 0%, transparent 60%)";
  } else if (aqi > 100 && aqi <= 200) {
    // UNHEALTHY: Red, stressed, mask, hunched
    shirtColor = '#ef4444'; // red-500
    shoulderPath = "M 30 290 C 50 220 150 220 170 290 Z"; // Heavily hunched
    eyeProps = { d: "M 78 122 Q 85 118 92 122 M 108 122 Q 115 118 122 122", stroke: "#451a03", width: 4 }; // Stressed eyes
    mouthProps = { d: "M 90 150 Q 100 140 110 150", stroke: "#451a03", fill: "none", width: 4 }; // Frown
    eyebrowProps = { d: "M 75 100 L 95 110 M 105 110 L 125 100" }; // Angry/stressed brows
    hasMask = true;
    headOffsetY = 15;
    bgGradient = "radial-gradient(circle, rgba(239, 68, 68, 0.15) 0%, transparent 60%)";
    sweatVisible = 1;
  } else if (aqi > 200) {
    // HAZARDOUS: Purple, very sick, heavy mask, deeply hunched
    shirtColor = '#a855f7'; // purple-500
    skinColor = '#d9f99d'; // slight green tint for sickness
    shoulderPath = "M 25 295 C 60 230 140 230 175 295 Z"; // Shrunk posture
    eyeProps = { d: "M 80 116 L 90 120 M 110 120 L 120 116", stroke: "#451a03", width: 4 }; // Super stressed/sick
    mouthProps = { d: "M 90 150 Q 100 135 110 150", stroke: "#451a03", fill: "none", width: 4 }; // Deep frown
    eyebrowProps = { d: "M 75 100 L 95 112 M 105 112 L 125 100" };
    hasMask = true;
    headOffsetY = 24;
    bgGradient = "radial-gradient(circle, rgba(168, 85, 247, 0.15) 0%, transparent 60%)";
    sweatVisible = 1;
    fogVisible = 1;
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center">
      {/* Background Glow */}
      <motion.div 
        className="absolute inset-0 z-0 transition-all duration-1000"
        style={{ background: bgGradient }}
      />

      {/* Container with gentle breathing float */}
      <motion.div 
        animate={{ y: [-5, 5, -5] }}
        transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
        className="relative z-10 w-64 h-80 [perspective:1000px]"
      >
        <svg viewBox="0 0 200 300" className="w-full h-full drop-shadow-2xl overflow-visible filter">

          {/* Body/Shirt */}
          <motion.path 
            initial={false}
            animate={{ d: shoulderPath, fill: shirtColor }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
          />
          <motion.path 
            d="M 60 220 L 140 220 L 140 290 L 60 290 Z"
            fill={shirtColor}
            initial={false}
            animate={{ y: headOffsetY }}
            transition={{ duration: 0.8 }}
            className="opacity-0" // Just an underlying filler structure, we rely mostly on the curve
          />

          {/* Neck */}
          <motion.g animate={{ y: headOffsetY }} transition={{ duration: 0.8 }}>
            <rect x="85" y="150" width="30" height="40" fill={skinColor} rx="10" />
            <rect x="85" y="150" width="30" height="15" fill="#ca8a04" opacity="0.2" /> {/* neck shadow */}
          </motion.g>

          {/* Head & Face Group */}
          <motion.g 
            animate={{ y: headOffsetY }} 
            transition={{ duration: 0.8, ease: "backOut" }}
          >
            {/* Face Shape */}
            <motion.rect 
              initial={false}
              animate={{ fill: skinColor }}
              x="55" y="55" width="90" height="110" rx="45" 
            />
            {/* Cheeks */}
            <circle cx="75" cy="135" r="8" fill="#ef4444" opacity="0.15" />
            <circle cx="125" cy="135" r="8" fill="#ef4444" opacity="0.15" />

            {/* Hair */}
            <path d="M 50 85 C 50 30 150 30 150 85 C 160 50 40 50 50 85" fill="#451a03" />
            <path d="M 50 70 C 70 30 130 30 150 70 C 130 50 70 50 50 70" fill="#78350f" />
            <path d="M 50 85 Q 100 55 150 85 L 145 75 Q 100 45 55 75 Z" fill="#290f01" />

            {/* Eyes */}
            <motion.path 
              initial={false}
              animate={{ d: eyeProps.d, stroke: eyeProps.stroke, strokeWidth: eyeProps.width }}
              fill="none" strokeLinecap="round" strokeLinejoin="round"
              transition={{ duration: 0.5 }}
            />

            {/* Eyebrows */}
            <motion.path 
              initial={false}
              animate={{ d: eyebrowProps.d }}
              stroke="#451a03" strokeWidth="3" fill="none" strokeLinecap="round" strokeLinejoin="round"
              transition={{ duration: 0.5 }}
            />

            {/* Mouth */}
            <motion.path 
              initial={false}
              animate={{ d: mouthProps.d, stroke: mouthProps.stroke, fill: mouthProps.fill, strokeWidth: mouthProps.width }}
              strokeLinecap="round" strokeLinejoin="round"
              transition={{ duration: 0.5 }}
            />

            {/* Sweat Drop for stress */}
            <motion.g 
              initial={false}
              animate={{ opacity: sweatVisible }}
              transition={{ duration: 0.5 }}
            >
              <path d="M 65 95 Q 65 105 70 105 Q 75 105 75 95 Q 70 85 65 95 Z" fill="#60a5fa" opacity="0.8" />
            </motion.g>

            {/* Face Mask - Animates in for dangerous/hazardous */}
            <AnimatePresence>
              {hasMask && (
                <motion.g
                  initial={{ opacity: 0, y: 10, scale: 0.9 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: 10, scale: 0.9 }}
                  transition={{ type: "spring", stiffness: 200, damping: 20 }}
                >
                  {/* Mask bands */}
                  <path d="M 60 130 L 45 115" stroke="#cbd5e1" strokeWidth="2" />
                  <path d="M 140 130 L 155 115" stroke="#cbd5e1" strokeWidth="2" />
                  <path d="M 60 150 L 50 160" stroke="#cbd5e1" strokeWidth="2" />
                  <path d="M 140 150 L 150 160" stroke="#cbd5e1" strokeWidth="2" />

                  {/* Mask base */}
                  <rect x="60" y="125" width="80" height="40" rx="15" fill="#f8fafc" />
                  <rect x="65" y="125" width="70" height="40" rx="12" fill="#e2e8f0" />
                  <rect x="60" y="125" width="80" height="40" rx="15" fill="none" stroke="#cbd5e1" strokeWidth="1" />

                  {/* Mask pleats */}
                  <path d="M 65 135 L 135 135" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" />
                  <path d="M 65 145 L 135 145" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" />
                  <path d="M 65 155 L 135 155" stroke="#cbd5e1" strokeWidth="1.5" strokeLinecap="round" />
                </motion.g>
              )}
            </AnimatePresence>
          </motion.g>

          {/* Floating Smog/Fog for hazardous */}
          <AnimatePresence>
            {fogVisible === 1 && (
              <motion.g
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
              >
                <motion.circle cx="30" cy="180" r="20" fill="#a1a1aa" opacity="0.3" filter="blur(5px)" 
                  animate={{ y: [-10, 10, -10], x: [-5, 5, -5] }} transition={{ duration: 5, repeat: Infinity }} />
                <motion.circle cx="170" cy="150" r="25" fill="#a1a1aa" opacity="0.3" filter="blur(6px)"
                  animate={{ y: [10, -10, 10], x: [5, -5, 5] }} transition={{ duration: 6, repeat: Infinity }} />
                <motion.circle cx="150" cy="240" r="30" fill="#a1a1aa" opacity="0.4" filter="blur(8px)"
                  animate={{ y: [-15, 15, -15], x: [10, -10, 10] }} transition={{ duration: 7, repeat: Infinity }} />
                <motion.circle cx="40" cy="260" r="25" fill="#a1a1aa" opacity="0.4" filter="blur(8px)"
                  animate={{ y: [15, -15, 15], x: [-10, 10, -10] }} transition={{ duration: 5.5, repeat: Infinity }} />
              </motion.g>
            )}
          </AnimatePresence>

        </svg>
      </motion.div>
    </div>
  );
}
